# W2.R1 S7 adjudication D: kicker reconstruction parity vs Sleeper's PUBLIC 2025 weekly kicker stat lines (read-only public API; 2025 only). Inner join on (gsis_id, week): only kicker-weeks present on both sides are compared.
suppressMessages({ library(data.table); library(jsonlite); library(nflreadr) })
cd <- "scripts/w2r1/cache"; dir.create(cd, FALSE, TRUE)
if (!file.exists(file.path(cd, "sleeper_players.json"))) system2("curl", c("-s", "--max-time", "120", "https://api.sleeper.app/v1/players/nfl", "-o", file.path(cd, "sleeper_players.json")))
for (w in 1:18) { f <- file.path(cd, sprintf("sleeper_stats_2025_w%d.json", w)); if (!file.exists(f)) system2("curl", c("-s", "--max-time", "60", sprintf("https://api.sleeper.app/v1/stats/nfl/regular/2025/%d", w), "-o", f)) }
pl <- fromJSON(file.path(cd, "sleeper_players.json")); gs <- rbindlist(lapply(names(pl), function(id) { x <- pl[[id]]; if (!identical(x$position, "K") || is.null(x$gsis_id)) NULL else data.table(sid = id, gsis = x$gsis_id) }))
rows <- merge(rbindlist(lapply(1:18, function(w) { s <- fromJSON(file.path(cd, sprintf("sleeper_stats_2025_w%d.json", w))); rbindlist(lapply(intersect(names(s), gs$sid), function(id) { x <- s[[id]]; g <- function(k) if (is.null(x[[k]])) 0 else x[[k]]
  data.table(week = w, sid = id, fg0 = g("fgm_0_19"), fg20 = g("fgm_20_29"), fg30 = g("fgm_30_39"), fg40 = g("fgm_40_49"), fg50 = g("fgm_50_59") + g("fgm_60p"), m0 = g("fgmiss_0_19"), m20 = g("fgmiss_20_29"), m30 = g("fgmiss_30_39"), m40 = g("fgmiss_40_49"), m50 = g("fgmiss_50_59") + g("fgmiss_60p"), xpm = g("xpm"), xpmiss = g("xpmiss")) }), fill = TRUE) }), fill = TRUE), gs, by = "sid")
a <- fread("scripts/w2r1/cache/s4_fg_attempts.csv")[season == 2025]
mine <- a[, .(fg0 = sum(made[bin == "b0_19"]), fg20 = sum(made[bin == "b20_29"]), fg30 = sum(made[bin == "b30_39"]), fg40 = sum(made[bin == "b40_49"]), fg50 = sum(made[bin %in% c("b50_59", "b60p")]), m0 = sum(1 - made[bin == "b0_19"]), m20 = sum(1 - made[bin == "b20_29"]), m30 = sum(1 - made[bin == "b30_39"]), m40 = sum(1 - made[bin == "b40_49"]), m50 = sum(1 - made[bin %in% c("b50_59", "b60p")])), by = .(week, gsis = kicker)]
d <- merge(rows, mine, by = c("week", "gsis"), suffixes = c(".sl", ".me")); res <- list(n_kicker_weeks_compared = nrow(d), n_kicker_weeks_nflverse = nrow(unique(a[, .(kicker, week)])), note = "Sleeper player dump carries gsis ids for ~63 current kickers: coverage is partial (reported), parity within the overlap is the evidence")
for (c in c("fg0", "fg20", "fg30", "fg40", "fg50", "m0", "m20", "m30", "m40", "m50")) res[[c]] <- list(exact_rate = mean(d[[paste0(c, ".sl")]] == d[[paste0(c, ".me")]]), sleeper = sum(d[[paste0(c, ".sl")]]), mine = sum(d[[paste0(c, ".me")]]))
pb <- as.data.table(load_pbp(2025))[season_type == "REG" & play_type == "extra_point"]; xp <- pb[, .(xpm_me = sum(extra_point_result == "good", na.rm = TRUE), xpmiss_me = sum(extra_point_result %in% c("failed", "blocked"), na.rm = TRUE)), by = .(week, gsis = kicker_player_id)]
dx <- merge(rows[, .(week, gsis, xpm, xpmiss)], xp, by = c("week", "gsis")); res$xpm <- list(n = nrow(dx), exact_rate = mean(dx$xpm == dx$xpm_me), sleeper = sum(dx$xpm), mine = sum(dx$xpm_me)); res$xpmiss <- list(exact_rate = mean(dx$xpmiss == dx$xpmiss_me), sleeper = sum(dx$xpmiss), mine = sum(dx$xpmiss_me))
write_json(res, "scripts/w2r1/results/s7_k_parity.json", auto_unbox = TRUE, pretty = TRUE, digits = 6); cat(toJSON(res, auto_unbox = TRUE), "\n")
